import {money,quote,strategies,payoff,risk,validateQuote} from './pricing.js';
import {account,metrics,buyingPower,reserved,fund,committed} from './accounting.js';
import {preview,execute,close,stock} from './execution.js';
import {fresh,load,save,restore,parseCSV,csv,KEY} from './storage.js';
import {lessons,challenges} from './lessons.js';
let loaded;try{loaded=load(localStorage)}catch{loaded={state:fresh(),warning:'Browser storage is unavailable. Export a backup before leaving.',blocked:true}}let state=loaded.state,storageBlocked=loaded.blocked,warning=loaded.warning,order=null,lessonIndex=0;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),usd=n=>Number.isFinite(n)?n.toLocaleString('en-US',{style:'currency',currency:'USD'}):'Unlimited',num=id=>Number($('#'+id).value),val=id=>$('#'+id).value;
const pages=['Dashboard','Practice Trading','Portfolio','Guided Lessons','Challenges','Journal','Settings'],icons=['◈','↗','▥','▤','◎','✎','⚙'];
const A=()=>state.accounts[state.mode],sim=()=>state.mode!=='snapshot',dayDate=d=>new Date(Date.parse(state.market.base+'T12:00:00Z')+d*86400000).toISOString().slice(0,10),days=e=>Math.max(0,Math.round((Date.parse(e+'T12:00:00Z')-Date.parse(dayDate(state.market.day)+'T12:00:00Z'))/86400000));
const ticker=()=>sim()?'DEMO':($('#ticker')?.value||state.snapshots[0]?.ticker||'DEMO');
const stockPrice=t=>sim()?state.market.spot:(state.snapshots.filter(q=>q.ticker===t).sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp))[0]?.underlying||A().stocks[t]?.basis||0);
function getQuote(type,k,p,strict=false){if(sim())return quote(type,state.market.spot,k,days(p.expiration),state.market.iv);const q=state.snapshots.filter(q=>q.type===type&&q.strike===k&&q.ticker===p.ticker&&q.expiration===p.expiration).sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp))[0];if(!q)throw Error('No matching snapshot. Add all legs with the same ticker and expiration first.');if(strict)validateQuote(q);return {...q,mid:money((q.bid+q.ask)/2)}}
const mark=(p,liquidation)=>money(p.legs.reduce((n,l)=>{const q=getQuote(l.type,l.strike,p);return n+l.side*(liquidation?(l.side>0?q.bid:q.ask):q.mid)*p.qty*100},0));
function M(){return metrics(A(),mark,stockPrice)}
function toast(text){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),6500)}
function persist(history=true){if(history){A().history.push(M().equity);A().history=A().history.slice(-500)}try{if(storageBlocked)throw Error('Storage is blocked to preserve unreadable data. Restore a valid backup or reset in Settings.');save(localStorage,state)}catch(e){warning='Changes are in memory only. '+e.message;toast(warning)}}
function act(fn){try{fn()}catch(e){toast(e.message)}}
function chart(values,label,xlabel='Recorded account events',ylabel='USD'){const vals=values.length?values:[0],min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,1),points=vals.map((v,i)=>`${45+i*620/Math.max(vals.length-1,1)},${175-(v-min)/range*140}`).join(' ');return `<svg class="chart" viewBox="0 0 710 215" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b3ef7c" stop-opacity=".16"/><stop offset="1" stop-color="#b3ef7c" stop-opacity="0"/></linearGradient></defs><line x1="45" y1="35" x2="665" y2="35"/><line x1="45" y1="105" x2="665" y2="105"/><line x1="45" y1="175" x2="665" y2="175"/><polygon class="fill" points="45,175 ${points} 665,175"/><polyline points="${points}"/><text x="45" y="22">${esc(ylabel)} · ${usd(max)}</text><text x="45" y="202">${esc(xlabel)}</text><text x="590" y="202">${usd(min)}</text></svg>`}
function source(){return sim()?`Theoretical · DEMO · Simulation ${dayDate(state.market.day)} (paused clock)`:'Manual snapshots · Not live · Stale after 15 minutes'}
function shell(){const page=decodeURIComponent(location.hash.slice(1))||'Dashboard',selected=pages.includes(page)?page:'Dashboard';$('#app').innerHTML=`<aside><div class="brand"><span>◒</span> papermoney</div><div class="brand-note">A LITTLE PRACTICE. A LOT OF CLARITY.</div><nav aria-label="Main navigation">${pages.map((p,i)=>`<a href="#${encodeURIComponent(p)}" class="${p===selected?'active':''}" ${p===selected?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icons[i]}</span>${p}</a>`).join('')}</nav><div class="aside-foot"><span class="positive">● Your learning space</span><br>Make mistakes. Ask questions.<br>Build confidence, one trade at a time.</div></aside><main><header class="topbar"><span class="badge">● Paper trading · No real money</span><label><span class="sr-only">Account workspace</span><select id="mode" class="mode"><option value="sim">Simulated practice</option><option value="snapshot">Manual snapshot practice</option><option value="scenario">Isolated modeled scenario</option></select></label></header>${warning?`<div class="notice" role="alert">${esc(warning)}</div>`:''}<div id="page"></div><footer class="footnote">Fictional money. Educational practice only. No brokerage connection. Prices: ${esc(source())}.<br>Saved on this browser only; clearing browser data can erase progress. Export backups in Settings.<details><summary>Pricing, execution & expiration assumptions</summary><p>Black–Scholes European model, zero interest and dividends, constant implied volatility per scenario, 365-day year. Real equity options can be American-style, with dividends, early exercise, assignment and share-delivery funding risks. Those mechanics are not simulated here. At expiration, theoretical options cash-settle to intrinsic value exactly once. At covered-call expiration, committed shares are sold at the terminal stock price to fund cash settlement. This educational liquidation is recorded separately. Snapshot positions never expire based on this simulation clock; use the explicit settlement action with an entered underlying price. This educational cash settlement does not reproduce brokerage behavior.</p><p>Buy at ask, sell at bid; every spread leg fills atomically. Simulated bid/ask is midpoint ± max($0.01, 2.5% of theoretical value), floored at zero. No fees, quoted-size liquidity, slippage, or actual fills are simulated. Open equity uses midpoint marks; estimated liquidation uses the opposite bid/ask side. Collateral is reserved cash, not an extra deduction from equity. Snapshot marks remain the last manually entered quotes, even if stale; stale fills are blocked.</p><p>Greeks are estimates per share: delta per $1 stock move; gamma change in delta per $1; theta dollar change over one calendar day; vega dollar change for +1 percentage point IV. Expiration payoff is different from pre-expiration market value.</p></details></footer></main><dialog id="dialog"></dialog>`;$('#mode').value=state.mode;$('#mode').onchange=()=>{state.markets??={};if(state.mode!=='snapshot')state.markets[state.mode]=structuredClone(state.market);state.mode=val('mode');if(state.mode!=='snapshot')state.market=structuredClone(state.markets[state.mode]||fresh().market);persist(false);render()};({Dashboard:dashboard,'Practice Trading':practice,Portfolio:portfolio,'Guided Lessons':learning,Challenges:challengePage,Journal:journal,Settings:settings})[selected]();}
function render(){shell()}
const head=(tag,title,desc,action='')=>`<div class="pagehead"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</div>`;
function transactions(limit=10){return A().ledger.slice(0,limit).map(t=>`<div class="listitem split"><div>${esc(t.text)}<br><small>${esc(t.timestamp)}</small></div><span class="${t.amount>=0?'positive':'negative'}">${t.amount>=0?'+':''}${usd(t.amount)}</span></div>`).join('')||'<div class="empty">Your first trade starts the story.</div>'}
function positionsTable(){return `<div class="table-wrap"><table><thead><tr><th>Position</th><th>Qty</th><th>Expiration</th><th>Mark value</th><th>Unrealized P/L</th><th>Collateral</th><th>Action</th></tr></thead><tbody>${A().positions.map(p=>`<tr><td>${esc(p.ticker)}<br><small>${esc(p.strategy)}</small></td><td>${p.qty}</td><td>${p.expiration}</td><td>${usd(mark(p,false))}</td><td class="${mark(p,false)-p.debit>=0?'positive':'negative'}">${usd(mark(p,false)-p.debit)}</td><td>${usd(p.collateral)}</td><td><button data-close="${esc(p.id)}">Close</button> ${!sim()?`<button data-settle="${esc(p.id)}">Settle expiry</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No open options. Start with a small practice trade.</td></tr>'}</tbody></table></div>`}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>act(()=>{const p=A().positions.find(p=>p.id===b.dataset.close),credit=mark(p,true);modal(`<h2>Close ${esc(p.strategy)}</h2><p>Opposite-side fills produce ${usd(credit)} ${credit>=0?'credit':'debit'}. Realized P/L: ${usd(credit-p.debit)}.</p><p class="muted">Every leg closes together. ${source()}</p><button id="confirmClose" class="primary">Confirm close</button>`);$('#confirmClose').onclick=()=>act(()=>{close(A(),p.id,(t,k,p)=>getQuote(t,k,p,true));persist();$('#dialog').close();render();toast('Position closed; collateral released. Add your reflection in Journal.')})}));document.querySelectorAll('[data-settle]').forEach(b=>b.onclick=()=>{const p=A().positions.find(p=>p.id===b.dataset.settle);modal(`<h2>Educational expiration settlement</h2><p>Only available after the real expiration date. Enter the final underlying price from your source. This cash-settles all legs; no shares are delivered.</p><label>Final stock price<input id="settlePrice" type="number" min="0" step=".01"></label><button id="settleConfirm">Confirm cash settlement</button>`);$('#settleConfirm').onclick=()=>act(()=>{if(Date.now()<Date.parse(p.expiration+'T23:59:59Z'))throw Error('This snapshot position has not expired');const s=num('settlePrice');if(!Number.isFinite(s)||s<0||val('settlePrice')==='')throw Error('Enter a valid final price');close(A(),p.id,null,s);persist();$('#dialog').close();render()})})}
function dashboard(){const m=M(),change=m.equity-A().capital;$('#page').innerHTML=head('Your practice, in perspective','Room to grow.','A safe place to understand the market, one decision at a time.','<a href="#Practice%20Trading"><button class="primary">New practice trade ↗</button></a>')+`<div class="grid stats">${[['Cash balance',A().cash,'Cash after premiums and stock purchases.'],['Buying power',buyingPower(A()),'Cash available after collateral reservations.'],['Reserved collateral',reserved(A()),'Cash locked to support short-option obligations.'],['Realized P/L',A().realized,'Profit or loss from closed trades, excluding deposits.']].map(([t,v,d])=>`<div class="card stat"><small>${t}</small><div class="number">${usd(v)}</div><div class="metric-help">${d}</div></div>`).join('')}</div><div class="grid cols"><section class="card"><div class="split"><h2>Account equity</h2><span class="pill">${state.mode==='snapshot'?'MANUAL QUOTES':'SIMULATED'}</span></div><div class="number big">${usd(m.equity)}</div><div class="${change>=0?'positive':'negative'}">${change>=0?'+':''}${usd(change)} since funding · ${usd(m.unrealized)} unrealized</div>${chart(A().history,'Account equity history in USD')}<div class="metric-help">Cash + shares + signed midpoint option values. Estimated liquidation: ${usd(m.liquidation)}. Deposits appear in history and are excluded from P/L.</div></section><section class="card"><div class="eyebrow">Small steps, real understanding</div><h2 style="margin-top:16px">Your next chapter</h2><p class="muted">Learn what an option actually gives you before putting a strategy to work.</p><div class="split"><small>Curriculum progress</small><small>${state.completed.length} / 14</small></div><div class="progress"><span style="width:${state.completed.length/14*100}%"></span></div><a href="#Guided%20Lessons"><button>Continue learning →</button></a><p class="tip">A good trade starts with knowing what you could lose, not just what you could make.</p></section></div><section class="card section-gap"><div class="split"><h2>Open positions <span class="pill">${A().positions.length}</span></h2><a href="#Portfolio">View portfolio →</a></div>${positionsTable()}</section><div class="grid cols section-gap"><section class="card"><h2>Recent transactions</h2>${transactions(4)}</section><a class="card hero-link learning-banner" href="#Challenges"><div class="eyebrow">Put your knowledge to work</div><h2 style="margin-top:14px">A challenge, not a gamble.</h2><p class="muted">Eight focused exercises. Clear feedback. No impact on your practice portfolio.</p><span class="positive">Explore challenges →</span></a></div>`;bindClose()}
function practice(){const exp=sim()?[dayDate(state.market.day+30),dayDate(state.market.day+1),dayDate(state.market.day+7),dayDate(state.market.day+60)]:[...new Set(state.snapshots.map(q=>q.expiration))];$('#page').innerHTML=head('Learn by doing','Practice trading','Explore a strategy. Understand the risk. Make the decision.')+`<div class="source">${esc(source())}</div>${state.mode==='scenario'?'<div class="notice">Isolated modeled estimates based on your last selected snapshot. Separate funds and positions; no snapshot quotes are used for valuation here.</div>':''}${sim()?`<section class="card section-gap"><div class="split"><h2>Market lab</h2><span class="pill">CLOCK ADVANCES ONLY WHEN YOU ASK</span></div><div class="fields"><label>Stock price · USD<input id="spot" type="number" min=".01" step=".01" value="${state.market.spot}"></label><label>Implied volatility · %<input id="iv" type="number" min="0" max="500" step="1" value="${state.market.iv*100}"></label><label>Scenario preset<select id="preset">${['Rising market','Falling market','Sideways market','Volatility spike','Post-event volatility crush','Approaching expiration'].map(p=>`<option ${p===state.market.preset?'selected':''}>${p}</option>`).join('')}</select></label></div><div class="row"><button id="applyMarket">Apply market inputs</button><label>Advance days<input id="advanceDays" type="number" value="1" min="1" max="3650"></label><button id="advance">Advance clock →</button><span class="source">${dayDate(state.market.day)} · Scenario steps are deterministic.</span></div></section>`:snapshotForm()}<div class="grid cols section-gap"><section class="card"><h2>Options chain</h2><div class="fields two"><label>Underlying<select id="ticker">${(sim()?['DEMO']:[...new Set(state.snapshots.map(q=>q.ticker))]).map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Expiration<select id="expiration">${exp.map(e=>`<option>${e}</option>`).join('')}</select></label></div><div id="chain"></div><details><summary>How to read the chain</summary>Calls benefit from higher prices; puts benefit from lower prices. ITM means intrinsic value is positive, OTM means zero intrinsic value; ATM is within $0.01 of strike. Greeks use per-share units (see page footer). Snapshots have no inferred IV or Greeks.</details></section><section class="card"><h2>Build your trade</h2><label>Strategy<select id="strategy">${Object.keys(strategies).map(s=>`<option>${s}</option>`).join('')}</select></label><div class="fields two"><label>Contracts<input id="qty" type="number" value="1" min="1" max="100"></label><label>Lower / single strike<input id="low" type="number" value="100" min=".01" step=".5"></label><label>Upper strike · spreads<input id="high" type="number" value="105" min=".01" step=".5"></label></div><p class="tip">One equity option contract represents 100 shares. Start small and check maximum loss.</p><button id="preview" class="primary">Review order →</button><hr><h3>Stock practice</h3><label>Whole shares · negative to sell<input id="shares" type="number" step="1" value="100"></label><p class="source">Stock fills at the displayed underlying price, with no spread. Shares committed to calls cannot be sold.</p><button id="stockTrade">Review stock trade</button></section></div>`;
if(sim()){$('#applyMarket').onclick=()=>act(()=>{const s=num('spot'),iv=num('iv')/100;if(!Number.isFinite(s)||s<.01||s>1e6||!Number.isFinite(iv)||iv<0||iv>5)throw Error('Enter a positive price and IV between 0% and 500%');state.market.spot=s;state.market.iv=iv;persist();render()});$('#advance').onclick=()=>act(()=>{const n=num('advanceDays');if(!Number.isInteger(n)||n<1||n>3650)throw Error('Advance 1–3650 whole days');const p=val('preset');state.market.preset=p;for(let i=0;i<n;i++){state.market.day++;if(p==='Rising market')state.market.spot=money(state.market.spot*1.01);if(p==='Falling market')state.market.spot=money(Math.max(.01,state.market.spot*.99));if(p==='Sideways market')state.market.spot=money(Math.max(.01,state.market.spot+(state.market.day%2?.15:-.15)));if(p==='Volatility spike')state.market.iv=.8;if(p==='Post-event volatility crush')state.market.iv=.15;for(const pos of [...A().positions])if(!days(pos.expiration))close(A(),pos.id,null,state.market.spot)}persist();render();toast('Clock advanced. Expired contracts were cash-settled.')});$('#preset').onchange=()=>{if(val('preset')==='Approaching expiration')$('#advanceDays').value=25}}
else bindSnapshots();$('#expiration').onchange=chain;$('#ticker').onchange=chain;chain();$('#preview').onclick=()=>act(reviewOrder);$('#stockTrade').onclick=()=>act(()=>{const t=ticker(),q=num('shares'),s=stockPrice(t);if(!sim()){const qs=state.snapshots.filter(x=>x.ticker===t);if(!qs.length)throw Error('Add a snapshot first');validateQuote(qs.sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp))[0])}modal(`<h2>Review stock trade</h2><p>${q>0?'Buy':'Sell'} ${Math.abs(q)} ${esc(t)} shares at ${usd(s)} each. Total: ${usd(Math.abs(q*s))}.</p><button id="stockConfirm" class="primary">Confirm stock trade</button>`);$('#stockConfirm').onclick=()=>act(()=>{stock(A(),t,q,s);persist();$('#dialog').close();render()})})}
function chain(){const t=ticker(),e=val('expiration');if(!e){$('#chain').innerHTML='<p class="empty">Add fresh snapshots to build your options chain.</p>';return}let strikes=sim()?Array.from({length:9},(_,i)=>money(Math.max(.01,Math.round(state.market.spot/5)*5+(i-4)*5))):[...new Set(state.snapshots.filter(q=>q.ticker===t&&q.expiration===e).map(q=>q.strike))].sort((a,b)=>a-b);$('#chain').innerHTML=`<div class="split"><strong>${esc(t)} <span class="positive">${usd(stockPrice(t))}</span></strong><small>${esc(source())}</small></div><div class="table-wrap"><table><thead><tr><th>Strike</th><th>Type · status</th><th>Bid</th><th>Ask</th><th>Mid</th><th>IV</th><th>Δ</th><th>Γ</th><th>Θ/day</th><th>Vega/1%</th><th>Quote time / source</th></tr></thead><tbody>${strikes.map(k=>['call','put'].map(type=>{let q;try{q=getQuote(type,k,{ticker:t,expiration:e})}catch{return ''}const itm=type==='call'?stockPrice(t)>k:stockPrice(t)<k,status=Math.abs(stockPrice(t)-k)<.01?'ATM':itm?'ITM':'OTM';return `<tr><td><button data-strike="${k}" data-type="${type}">${k.toFixed(2)}</button></td><td>${type} <span class="${itm?'positive':'muted'}">${status}</span></td><td>${usd(q.bid)}</td><td>${usd(q.ask)}</td><td>${usd(q.mid)}</td><td>${sim()?(state.market.iv*100).toFixed(0)+'%':'Unavailable'}</td>${['delta','gamma','theta','vega'].map(g=>`<td>${sim()?q[g].toFixed(3):'Unavailable'}</td>`).join('')}<td>${sim()?dayDate(state.market.day)+' · theoretical':esc(q.timestamp)+' · '+esc(q.source||'manual')}</td></tr>`}).join('')).join('')}</tbody></table></div>`;document.querySelectorAll('[data-strike]').forEach(b=>b.onclick=()=>{$('#low').value=b.dataset.strike;$('#high').value=Number(b.dataset.strike)+5;$('#strategy').value=b.dataset.type==='call'?'Long call':'Long put';$('#preview').focus()})}
function reviewOrder(){const t=ticker(),e=val('expiration');if(!e)throw Error('Choose an expiration');const p=preview(A(),val('strategy'),num('qty'),t,e,num('low'),num('high'),(type,k)=>getQuote(type,k,{ticker:t,expiration:e},true)),r=risk(p,A().stocks[t]?.basis||0);order={...p,id:crypto.randomUUID()};const low=Math.min(...p.legs.map(l=>l.strike)),high=Math.max(...p.legs.map(l=>l.strike)),xs=Array.from({length:31},(_,i)=>low*.65+(high*1.35-low*.65)*i/30);modal(`<div class="eyebrow">Order preview · ${esc(state.mode)} account</div><h2>${esc(p.strategy)}</h2>${p.legs.map(l=>`<p>${l.side>0?'Buy':'Sell'} ${p.qty} × ${esc(t)} ${e} ${l.strike} ${l.type} at ${usd(l.side>0?l.ask:l.bid)} / share × 100.</p>`).join('')}<div class="fields two">${[['Total '+(p.debit>=0?'debit':'credit'),usd(Math.abs(p.debit))],['Cash collateral',usd(p.collateral)],['Buying power after',usd(p.after)],['Maximum profit',usd(r.profit)],['Maximum loss',usd(Math.max(0,r.loss))],['Expiration break-even',usd(r.breakeven)]].map(([t,v])=>`<div><small>${t}</small><h3>${v}</h3></div>`).join('')}</div>${chart(xs.map(s=>payoff(p,s)+(p.strategy==='Covered call'?(s-(A().stocks[t]?.basis||0))*100*p.qty:0)),'Expiration profit/loss across stock prices',`Stock price ${usd(xs[0])} → ${usd(xs.at(-1))}`,'Expiration P/L')}<p class="tip">${p.strategy==='Covered call'?'Includes owned shares at their cost basis. Premium caps upside but does not remove stock downside.':p.strategy==='Cash-secured put'?'You earn a limited premium while accepting stock downside below the strike. Strike × 100 × contracts is reserved.':p.strategy.includes('spread')?'One long and one short option with matching symbol, expiration and quantity. Your upside and downside are bounded.':'You pay a premium for a right, not an obligation. You may lose the full premium.'} The chart shows expiration payoff, not the option’s value before expiration.</p><p class="source">${source()} · Buys fill at ask; sells at bid. No liquidity or actual execution simulation.</p><button id="confirmOrder" class="primary">Place paper trade</button>`);$('#confirmOrder').onclick=()=>act(()=>{const fresh=preview(A(),p.strategy,p.qty,t,e,num('low'),num('high'),(type,k)=>getQuote(type,k,{ticker:t,expiration:e},true));execute(A(),fresh,order.id);state.journal.unshift({id:crypto.randomUUID(),tradeId:order.id,mode:state.mode,reason:'',movement:'',holding:'',exit:'',risk:'',reflection:'',created:new Date().toISOString()});persist();$('#dialog').close();render();toast('Paper trade placed. A linked journal entry is ready.')})}
function modal(html){$('#dialog').innerHTML=`<div class="split" style="margin-bottom:18px"><span class="pill">PAPERMONEY</span><button id="dismiss" aria-label="Close dialog">×</button></div>${html}`;$('#dialog').showModal();$('#dismiss').onclick=()=>$('#dialog').close()}
function snapshotForm(){return `<section class="card section-gap"><h2>Manual quote workspace</h2><p class="muted">Copy a quote you are permitted to use. It is a saved snapshot, never a live feed. Trades require quotes no older than 15 minutes.</p><form id="snapshotForm"><div class="fields"><label>Ticker<input id="qTicker" required maxlength="10" value="AAPL"></label><label>Underlying · USD<input id="qSpot" type="number" min=".01" step=".01" required></label><label>Option type<select id="qType"><option value="call">Call</option><option value="put">Put</option></select></label><label>Strike<input id="qStrike" type="number" min=".01" step=".01" required></label><label>Expiration<input id="qExpiration" type="date" required></label><label>Bid<input id="qBid" type="number" min="0" step=".01" required></label><label>Ask<input id="qAsk" type="number" min="0" step=".01" required></label><label>Quote timestamp · local time<input id="qTime" type="datetime-local" required></label><label>Source note<input id="qSource" maxlength="200" placeholder="Manually copied from broker"></label></div><button class="primary" type="submit">Save quote</button></form><div class="row section-gap"><button id="csvTemplate">Download CSV example</button><button id="csvExport">Export snapshots CSV</button><label>Import CSV<input id="csvImport" type="file" accept=".csv,text/csv"></label><button id="exploreSnapshot">Explore modeled scenario</button></div><div class="table-wrap"><table><thead><tr><th>Symbol / contract</th><th>Bid / Ask</th><th>Timestamp / source</th><th>Freshness</th></tr></thead><tbody>${state.snapshots.map(q=>`<tr><td>${esc(q.ticker)} ${q.strike} ${q.type} · ${q.expiration}</td><td>${usd(q.bid)} / ${usd(q.ask)}</td><td>${esc(q.timestamp)}<br>${esc(q.source)}</td><td>${Date.now()-Date.parse(q.timestamp)>900000?'Stale · update required':'Fresh at render'}</td></tr>`).join('')}</tbody></table></div></section>`}
function addQuotes(qs){qs.forEach(q=>validateQuote(q));for(const q of qs){const ix=state.snapshots.findIndex(x=>x.ticker===q.ticker&&x.type===q.type&&x.strike===q.strike&&x.expiration===q.expiration);if(ix>=0)state.snapshots[ix]=q;else state.snapshots.push(q)}persist(false);render()}
function bindSnapshots(){$('#snapshotForm').onsubmit=e=>{e.preventDefault();act(()=>addQuotes([{ticker:val('qTicker').toUpperCase(),underlying:num('qSpot'),type:val('qType'),strike:num('qStrike'),expiration:val('qExpiration'),bid:num('qBid'),ask:num('qAsk'),timestamp:new Date(val('qTime')).toISOString(),source:val('qSource')}]))};$('#csvTemplate').onclick=()=>download('papermoney-quotes-example.csv',csv([{ticker:'AAPL',underlying:100,type:'call',strike:100,expiration:new Date(Date.now()+30*86400000).toISOString().slice(0,10),bid:2,ask:2.1,timestamp:new Date().toISOString(),source:'EXAMPLE ONLY: replace with your actual quote'}]),'text/csv');$('#csvExport').onclick=()=>download('papermoney-snapshots.csv',csv(state.snapshots),'text/csv');$('#csvImport').onchange=async e=>{try{const f=e.target.files[0];if(f.size>1e6)throw Error('CSV exceeds 1 MB');addQuotes(parseCSV(await f.text()))}catch(err){toast(err.message)}};$('#exploreSnapshot').onclick=()=>act(()=>{const q=state.snapshots.filter(q=>q.ticker===ticker()).at(-1);if(!q)throw Error('Save a snapshot first');state.markets??={};state.markets.sim??=structuredClone(state.market);if(state.accounts.scenario.positions.length&&!confirm('Reset the isolated modeled scenario account to explore this snapshot?'))return;state.accounts.scenario=account();state.market={spot:q.underlying,iv:.3,day:0,base:new Date().toISOString().slice(0,10),preset:'Sideways market'};state.markets.scenario=structuredClone(state.market);state.mode='scenario';persist(false);render();toast('Isolated model uses 30% assumed IV, not an implied estimate from the quote.')})}
function portfolio(){const m=M();$('#page').innerHTML=head('Keep the whole picture','Your portfolio','See your exposure, collateral and every step of your practice.')+`<div class="grid stats">${[['Equity',m.equity],['Unrealized P/L',m.unrealized],['Realized P/L',A().realized],['Estimated liquidation',m.liquidation]].map(([t,n])=>`<div class="card stat"><small>${t}</small><div class="number">${usd(n)}</div></div>`).join('')}</div><section class="card"><h2>Options</h2>${positionsTable()}</section><section class="card section-gap"><h2>Stock holdings</h2><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Shares</th><th>Cost basis / share</th><th>Current price</th><th>Committed shares</th><th>Unrealized P/L</th></tr></thead><tbody>${Object.entries(A().stocks).filter(([,s])=>s.qty).map(([t,s])=>`<tr><td>${esc(t)}</td><td>${s.qty}</td><td>${usd(s.basis)}</td><td>${usd(stockPrice(t))}</td><td>${committed(A(),t)}</td><td>${usd(s.qty*(stockPrice(t)-s.basis))}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No stock holdings.</td></tr>'}</tbody></table></div></section><section class="card section-gap"><h2>Transaction ledger</h2>${transactions(100)}</section>`;bindClose()}
function learning(){$('#page').innerHTML=head('Build your foundation','Guided lessons','Fourteen small lessons. A stronger understanding of every trade.')+`<div class="progress"><span style="width:${state.completed.length/14*100}%"></span></div><p class="source">${state.completed.length} of 14 lessons completed · Exercises and knowledge checks required</p><div class="grid lesson-grid">${lessons.map((l,i)=>`<section class="card lesson-card"><div class="split"><span class="lesson-num">LESSON ${String(i+1).padStart(2,'0')}</span><span class="pill">${state.completed.includes(l.id)?'✓ COMPLETED':'LEARN + PRACTICE'}</span></div><h2>${esc(l.title)}</h2><p class="muted">${esc(l.explanation.slice(0,150))}…</p><button data-lesson="${i}">${state.completed.includes(l.id)?'Revisit lesson':'Start lesson'} →</button></section>`).join('')}</div>`;document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>showLesson(Number(b.dataset.lesson)))}
function showLesson(i){const l=lessons[i];let exerciseCorrect=false,knowledgeCorrect=false;modal(`<div class="eyebrow">Lesson ${i+1} / 14</div><h2>${esc(l.title)}</h2><p>${esc(l.explanation)}</p><div class="notice"><strong>Walk through an example</strong><br>${esc(l.example)}</div><h3>Try it yourself</h3><p>${esc(l.exercise)}</p><label>Your answer · ${esc(l.unit||'number')}<input id="lessonAnswer" type="number" step="any"></label><div class="row section-gap"><button id="checkExercise">Check exercise</button><button id="hintLesson">Show hint</button></div><p id="exerciseResult" role="status"></p><h3>Knowledge check</h3><p>${esc(l.knowledgeCheck.question)}</p><label>Choose an answer<select id="knowledge"><option value="">Select…</option>${l.knowledgeCheck.options.map((o,j)=>`<option value="${j}">${esc(o)}</option>`).join('')}</select></label><button class="section-gap" id="checkKnowledge">Check understanding</button><p id="knowledgeResult" role="status"></p><button id="completeLesson" class="primary" disabled>Complete lesson</button><p class="source">Learn more: <a target="_blank" rel="noopener" href="${esc(l.source)}">Primary educational source ↗</a></p>`);const unlock=()=>$('#completeLesson').disabled=!(exerciseCorrect&&knowledgeCorrect);$('#hintLesson').onclick=()=>$('#exerciseResult').textContent=l.hint;$('#checkExercise').onclick=()=>{exerciseCorrect=val('lessonAnswer')!==''&&Math.abs(num('lessonAnswer')-l.answer)<.011;$('#exerciseResult').textContent=exerciseCorrect?'Correct. '+l.answerExplanation:'Try again. '+l.hint;unlock()};$('#checkKnowledge').onclick=()=>{knowledgeCorrect=val('knowledge')!==''&&Number(val('knowledge'))===l.knowledgeCheck.answer;$('#knowledgeResult').textContent=knowledgeCorrect?'Correct. '+l.knowledgeCheck.explanation:'Take another look at the example.';unlock()};$('#completeLesson').onclick=()=>{if(!exerciseCorrect||!knowledgeCorrect)return;if(!state.completed.includes(l.id))state.completed.push(l.id);persist(false);$('#dialog').close();render();toast('Lesson completed. Your progress is saved.')};}
function challengePage(){$('#page').innerHTML=head('Understanding over returns','Challenges','Practice a specific decision in an isolated exercise. Your portfolio stays separate.')+`<p class="source">${state.challenges.length} of ${challenges.length} completed</p><div class="grid lesson-grid">${challenges.map((c,i)=>`<section class="card lesson-card"><span class="lesson-num">CHALLENGE ${i+1} ${state.challenges.includes(c.id)?'✓':''}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.objective||c.explanation)}</p><button data-challenge="${i}">Take challenge →</button></section>`).join('')}</div>`;document.querySelectorAll('[data-challenge]').forEach(b=>b.onclick=()=>{const c=challenges[Number(b.dataset.challenge)];modal(`<div class="eyebrow">Isolated challenge · no account transactions</div><h2>${esc(c.title)}</h2><p>${esc(c.objective||c.explanation)}</p><div class="notice">${esc(c.startingConditions||c.example)}</div><p>${esc(c.exercise)}</p><label>Answer · ${esc(c.unit||'number')}<input id="challengeAnswer" type="number" step="any"></label><div class="row section-gap"><button id="challengeCheck" class="primary">Check answer</button><button id="challengeHint">Show hint</button></div><p id="challengeResult" role="status"></p><a href="${esc(c.source)}" target="_blank" rel="noopener">Primary source ↗</a>`);$('#challengeHint').onclick=()=>$('#challengeResult').textContent=c.hint;$('#challengeCheck').onclick=()=>{const ok=val('challengeAnswer')!==''&&Math.abs(num('challengeAnswer')-c.answer)<.011;$('#challengeResult').textContent=ok?'Correct. '+c.answerExplanation:'Not yet. '+c.hint;if(ok&&!state.challenges.includes(c.id)){state.challenges.push(c.id);persist(false)}}})}
function journal(){$('#page').innerHTML=head('Think before. Reflect after.','Trading journal','Record your reasoning and what you learned.','<button id="newJournal" class="primary">New entry +</button>')+`<div class="grid lesson-grid">${state.journal.filter(j=>j.mode===state.mode).map(j=>`<article class="card"><div class="source">${esc(j.created)} · ${j.tradeId?'Linked trade '+esc(j.tradeId.slice(0,8)):'General reflection'}</div><h2>${esc(j.reason||'Your trade, your reasoning')}</h2><p class="muted journal-text">${esc(j.reflection||'No reflection yet.')}</p><button data-journal="${esc(j.id)}">Edit journal entry</button></article>`).join('')||'<div class="card empty">Place a trade to create a linked entry, or start a general reflection.</div>'}</div>`;$('#newJournal').onclick=()=>editJournal();document.querySelectorAll('[data-journal]').forEach(b=>b.onclick=()=>editJournal(b.dataset.journal))}
function editJournal(id){const existing=state.journal.find(j=>j.id===id),j=existing||{id:crypto.randomUUID(),mode:state.mode,created:new Date().toISOString()};const fields=[['reason','Entry reasoning'],['movement','Expected price movement'],['holding','Expected holding period'],['exit','Planned exit'],['risk','Risk considered'],['reflection','Outcome and reflection']];modal(`<h2>Write it down.</h2><label>Linked trade<select id="journalTrade"><option value="">General reflection</option>${A().ledger.filter(t=>t.text.startsWith('Open ')).map(t=>`<option value="${esc(t.id)}" ${t.id===j.tradeId?'selected':''}>${esc(t.text)} · ${esc(t.id.slice(0,8))}</option>`).join('')}</select></label><div class="grid section-gap">${fields.map(([k,t])=>`<label>${t}<textarea id="journal-${k}" maxlength="10000">${esc(j[k]||'')}</textarea></label>`).join('')}</div><button id="saveJournal" class="primary section-gap">Save reflection</button>`);$('#saveJournal').onclick=()=>{for(const [k] of fields)j[k]=val('journal-'+k);j.tradeId=val('journalTrade');if(!existing)state.journal.unshift(j);persist(false);$('#dialog').close();render()}}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function settings(){$('#page').innerHTML=head('Make this space yours','Settings & data','Keep a backup and practice at your own pace.')+`<div class="grid cols"><section class="card"><h2>Practice funding</h2><p class="muted">Each workspace starts at $10,000. Funding changes create a ledger entry and never rewrite performance.</p><label>Deposit (+) or withdrawal (−) · USD<input id="funding" type="number" step=".01" value="1000"></label><button id="fund" class="primary section-gap">Record funding change</button><p class="source">Current workspace: ${esc(state.mode)} · Net capital: ${usd(A().capital)}</p><hr><h2>Backup & restore</h2><p class="muted">Accounts, quotes, journals and progress stay in this browser. They do not sync across devices. Export regularly.</p><button id="export">Export JSON backup</button><label class="section-gap">Restore backup · validated before replacement<input id="import" type="file" accept=".json,application/json"></label></section><section class="card"><h2>Start fresh</h2><p class="muted">Reset requires confirmation. Export a backup first.</p><button id="resetAccount" class="danger">Reset ${esc(state.mode)} account</button><p><button id="resetAll" class="danger">Reset all data</button></p><h3>Version 1.0</h3><p class="source">Storage schema v1. Unknown versions are rejected without overwriting saved data. No accounts, APIs or remote data transmission.</p><a href="https://github.com/aarondpana/papermoney" target="_blank" rel="noopener">Source code ↗</a></section></div>`;$('#fund').onclick=()=>act(()=>{fund(A(),num('funding'));persist();render();toast('Funding recorded.')});$('#export').onclick=()=>download('papermoney-backup.json',JSON.stringify(state,null,2));$('#import').onchange=async e=>{try{const f=e.target.files[0];if(f.size>1e7)throw Error('Backup exceeds 10 MB');const incoming=restore(await f.text());if(!confirm('Replace all current accounts and learning progress with this validated backup?'))return;state=incoming;storageBlocked=false;warning='';persist(false);render();toast('Backup restored.')}catch(err){toast('Import rejected: '+err.message)}};$('#resetAccount').onclick=()=>{if(confirm('Reset this account to $10,000 and remove its positions, transactions and journals?')){state.accounts[state.mode]=account();state.journal=state.journal.filter(j=>j.mode!==state.mode);persist(false);render()}};$('#resetAll').onclick=()=>{if(confirm('Reset all accounts, quotes, journals, lessons and challenges? Export a backup first.')){state=fresh();storageBlocked=false;warning='';persist(false);render()}}}
window.addEventListener('hashchange',render);render();


